let products=[],favorites=new Set(JSON.parse(localStorage.getItem('goltra-favorites')||'[]')),cart=JSON.parse(localStorage.getItem('goltra-cart')||'[]'),category='all',currentId=null,session=JSON.parse(localStorage.getItem('goltra-admin-session')||'null'),adminFilter='all';
const buttons=[...document.querySelectorAll('[data-filter]')],league=els('league'),team=els('team'),season=els('season'),search=els('search');
const mapProduct=p=>({...p,id:String(p.id),name:p.nombre,team:p.equipo||'Sin equipo',season:p.temporada||'Sin temporada',league:p.liga||'Sin clasificar',category:p.categoria||'clubs',description:p.descripcion||`${p.nombre}. Camiseta disponible en GOLTRA.`,image:p.imagen_path,images:[...(p.catalogo_producto_imagenes||[])].sort((a,b)=>a.orden-b.orden),estado_web:p.estado_web||'borrador',versiones_disponibles:p.versiones_disponibles||VERSIONS,tallas_disponibles:p.tallas_disponibles||SIZES.slice(0,7)});
async function loadCatalog(admin=false){
 try{
  const select='*,catalogo_producto_imagenes(*)';
  const rows=await request(`/rest/v1/catalogo_productos?select=${encodeURIComponent(select)}&order=orden.asc,nombre.asc`,{token:admin?session?.access_token:null});
  products=(rows||[]).map(mapProduct);refresh();
  if(admin)renderAdmin();
 }catch(error){els('empty-results').hidden=false;els('empty-results').textContent='No hemos podido cargar el catálogo. Inténtalo de nuevo en unos segundos.';toast(error.message)}
}
function saveFavorites(){localStorage.setItem('goltra-favorites',JSON.stringify([...favorites]));els('fav-count').textContent=favorites.size}
function categoryMatch(p){return category==='all'||category==='favorites'&&favorites.has(p.id)||category==='clubs'&&p.league!=='Selecciones'||category==='national'&&p.league==='Selecciones'||category==='retro'&&p.category==='retro'}
function setOptions(el,values,placeholder){const previous=el.value;el.replaceChildren(new Option(placeholder,''));unique(values).forEach(v=>el.add(new Option(v,v)));el.value=values.includes(previous)?previous:''}
function imageFor(p){return storageUrl(p.image||p.images.find(i=>i.es_principal)?.imagen_path||p.images[0]?.imagen_path)}
function startingPrice(p){const keys={Fan:'precio_fan',Player:'precio_player','Manga Larga':'precio_manga_larga',Infantil:'precio_infantil'};const prices=(p.versiones_disponibles||[]).map(v=>Number(p[keys[v]])).filter(v=>Number.isFinite(v)&&v>0);return prices.length?Math.min(...prices):Number(p.precio_fan||15.99)}
const heartIcon=()=>'<svg class="ui-heart" aria-hidden="true" viewBox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78Z"/></svg>';
function card(p,index){return `<article class="product-card ${p.estado_web==='agotado'?'is-sold-out':''}" data-id="${p.id}"><div class="product-image-wrap"><button class="product-image" data-open="${p.id}" aria-label="Ver ${p.name}"><span class="tag">${p.estado_web==='agotado'?'AGOTADA':p.category==='retro'?'RETRO CLUB':p.league==='Selecciones'?'SELECCIÓN':'CLUB'}</span><img src="${imageFor(p)}" alt="Camiseta ${p.name}" loading="lazy"><span class="product-arrow" aria-hidden="true"></span></button><button class="card-heart ${favorites.has(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="${favorites.has(p.id)?'Quitar de':'Añadir a'} favoritos">${heartIcon()}</button></div><button class="product-info" data-open="${p.id}"><div><h3>${p.name}</h3><p>${p.team} · ${p.season}</p><strong class="card-price">Desde ${money(startingPrice(p))}</strong></div><span>${String(index+1).padStart(2,'0')}</span></button></article>`}
function refresh(reset=false){
 const base=products.filter(categoryMatch);if(reset){league.value='';team.value='';season.value=''}
 setOptions(league,base.map(p=>p.league),'Todas las ligas');const byLeague=base.filter(p=>!league.value||p.league===league.value);
 setOptions(team,byLeague.map(p=>p.team),league.value==='Selecciones'?'Todos los países':'Todos los equipos');els('team-label').childNodes[0].textContent=league.value==='Selecciones'?'País':'Equipo';
 const byTeam=byLeague.filter(p=>!team.value||p.team===team.value);setOptions(season,byTeam.map(p=>p.season),'Todas las temporadas');
 const query=normalize(search.value);const shown=byTeam.filter(p=>(!season.value||p.season===season.value)&&(!query||normalize([p.name,p.team,p.league,p.season,p.modelo,p.category].join(' ')).includes(query)));
 els('products').innerHTML=shown.map(card).join('');els('result-count').textContent=`${shown.length} ${shown.length===1?'camiseta':'camisetas'}${query?` para “${search.value.trim()}”`:''}`;els('empty-results').hidden=shown.length>0;
 buttons.forEach(b=>{const active=b.dataset.filter===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});const activeFilters=[league.value,team.value,season.value].filter(Boolean).length;els('filter-toggle').innerHTML=`Filtrar por liga, equipo y temporada${activeFilters?` (${activeFilters})`:''} <span>${els('filter-toggle').getAttribute('aria-expanded')==='true'?'−':'+'}</span>`;els('clear-filters').disabled=category==='all'&&!league.value&&!team.value&&!season.value&&!query;bindCards();
}
function bindCards(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openProduct(b.dataset.open));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFavorite(b.dataset.favorite)})}
function setCategory(value){category=value;refresh(true);els('coleccion').scrollIntoView({behavior:'smooth'})}
buttons.forEach(b=>b.onclick=()=>setCategory(b.dataset.filter));league.onchange=()=>{team.value='';season.value='';refresh()};team.onchange=()=>{season.value='';refresh()};season.onchange=()=>refresh();search.oninput=()=>refresh();
els('clear-filters').onclick=()=>{search.value='';setCategory('all')};els('retro-link').onclick=()=>setCategory('retro');els('search-trigger').onclick=()=>{els('coleccion').scrollIntoView({behavior:'smooth'});setTimeout(()=>search.focus(),450)};els('favorites-trigger').onclick=()=>setCategory('favorites');
document.querySelectorAll('[data-quick-league]').forEach(b=>b.onclick=()=>{category='all';refresh(true);league.value=b.dataset.quickLeague;refresh();els('coleccion').scrollIntoView({behavior:'smooth'})});
function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);saveFavorites();refresh();if(currentId===id)updateDialogFavorite();toast(favorites.has(id)?'Guardada en favoritos':'Eliminada de favoritos')}
function updateDialogFavorite(){const saved=favorites.has(currentId);els('detail-favorite').innerHTML=heartIcon();els('detail-favorite').classList.toggle('saved',saved);els('detail-favorite').setAttribute('aria-label',saved?'Quitar de favoritos':'Añadir a favoritos')}
function productImages(p,version){const list=p.images.filter(image=>image.version===version).map(image=>image.imagen_path);if(!list.length&&p.image)list.push(p.image);return list.length?list:[null]}
function selectDetailImage(path,p){els('detail-image').src=storageUrl(path);els('detail-image').alt=`Camiseta ${p.name}`;const views=productImages(p,els('detail-version').value);els('gallery-position').textContent=views.length>1?`${Math.max(0,views.indexOf(path))+1} / ${views.length}`:'';document.querySelectorAll('[data-detail-image]').forEach(b=>b.classList.toggle('active',b.dataset.detailImage===(path||'')))}
function renderDetailGallery(p){const version=els('detail-version').value,images=productImages(p,version);els('detail-thumbs').innerHTML=images.length>1?images.map((path,i)=>`<button data-detail-image="${path||''}" class="${i===0?'active':''}"><img src="${storageUrl(path)}" alt="${version}, vista ${i+1} de ${p.name}"></button>`).join(''):'';document.querySelectorAll('[data-detail-image]').forEach(b=>b.onclick=()=>selectDetailImage(b.dataset.detailImage||null,p));selectDetailImage(images[0],p)}
function updateDetailSizes(){const p=products.find(x=>x.id===currentId);if(!p)return;const previous=els('detail-size').value,allowed=els('detail-version').value==='Infantil'?CHILD_SIZES:ADULT_SIZES,available=allowed.filter(size=>p.tallas_disponibles.includes(size));els('detail-size').replaceChildren(...available.map(size=>new Option(size,size)));els('detail-size').value=available.includes(previous)?previous:available.includes('M')?'M':available[0]||''}
function openProduct(id){
 const p=products.find(x=>x.id===id);if(!p)return;currentId=id;els('detail-title').textContent=p.name;els('detail-meta').textContent=`${p.league} · ${p.team} · ${p.season}`;els('detail-description').textContent=p.description;
 els('detail-version').replaceChildren(...p.versiones_disponibles.map(v=>new Option(v,v)));els('detail-version').value=p.versiones_disponibles[0]||'';renderDetailGallery(p);updateDetailSizes();els('detail-custom').checked=false;els('detail-patches').checked=false;els('custom-option').hidden=!p.permite_personalizacion;els('patch-option').hidden=!p.permite_parches;els('personal-fields').hidden=true;els('custom-name').value='';els('custom-number').value='';els('detail-size-guide').textContent=p.guia_tallas||'Las medidas de esta camiseta están pendientes. Escríbenos y te ayudamos a elegir talla.';const sold=p.estado_web==='agotado';els('sold-out-message').hidden=!sold;els('interest-button').disabled=sold;els('interest-button').textContent=sold?'Camiseta agotada':'Añadir al pedido';updatePrice();updateDialogFavorite();els('product-dialog').showModal();
}
function updatePrice(){const p=products.find(x=>x.id===currentId);if(!p)return;const key={Fan:'precio_fan',Player:'precio_player','Manga Larga':'precio_manga_larga',Infantil:'precio_infantil'}[els('detail-version').value];const total=Number(p[key]||18.99)+(els('detail-custom').checked?Number(p.suplemento_personalizacion||2):0)+(els('detail-patches').checked?Number(p.suplemento_parches||2):0);els('detail-price').textContent=money(total);els('personal-fields').hidden=!els('detail-custom').checked}
els('detail-version').onchange=()=>{const p=products.find(x=>x.id===currentId);if(p)renderDetailGallery(p);updateDetailSizes();updatePrice()};['detail-custom','detail-patches'].forEach(id=>els(id).onchange=updatePrice);els('detail-favorite').onclick=()=>toggleFavorite(currentId);els('zoom-trigger').onclick=()=>{els('zoom-image').src=els('detail-image').src;els('zoom-image').alt=els('detail-image').alt;els('image-dialog').showModal()};
els('interest-button').onclick=addCurrentToCart;

function saveCart(){localStorage.setItem('goltra-cart',JSON.stringify(cart));renderCart()}
function addCurrentToCart(){const p=products.find(x=>x.id===currentId);if(!p||p.estado_web==='agotado')return;const version=els('detail-version').value,size=els('detail-size').value;if(!version||!size){toast('Elige una versión y una talla');return}const custom=els('detail-custom').checked,patches=els('detail-patches').checked,name=els('custom-name').value.trim(),number=els('custom-number').value.trim();const signature=[p.id,version,size,custom,patches,name,number].join('|');let item=cart.find(x=>x.signature===signature);if(item)item.quantity++;else cart.push({signature,id:p.id,name:p.name,team:p.team,season:p.season,image:imageFor(p),version,size,custom,patches,customName:name,customNumber:number,unitPrice:Number(els('detail-price').textContent.replace(/[^0-9,]/g,'').replace(',','.')),quantity:1});saveCart();els('product-dialog').close();toast('Añadida a tu pedido')}
function renderCart(){const count=cart.reduce((sum,item)=>sum+item.quantity,0),subtotal=cart.reduce((sum,item)=>sum+item.unitPrice*item.quantity,0),shipping=count===0||count>=5?0:3;els('cart-count').textContent=count;els('cart-trigger').setAttribute('aria-label',`Ver pedido, ${count} ${count===1?'camiseta':'camisetas'}`);els('cart-empty').hidden=count>0;els('cart-items').innerHTML=cart.map((item,index)=>`<article class="cart-item"><img src="${item.image}" alt="Camiseta ${item.name}"><div class="cart-item-copy"><strong>${item.name}</strong><span>${item.team} · ${item.season}</span><span>${item.version} · Talla ${item.size}</span>${item.custom?`<span>Personalización: ${item.customName||'sí'}${item.customNumber?` · ${item.customNumber}`:''}</span>`:''}${item.patches?'<span>Con parches</span>':''}<strong>${money(item.unitPrice*item.quantity)}</strong></div><div class="cart-item-actions"><button data-quantity="${index}" data-delta="-1" aria-label="Restar una">−</button><span>${item.quantity}</span><button data-quantity="${index}" data-delta="1" aria-label="Añadir una">+</button><button data-remove="${index}" class="remove-item">Quitar</button></div></article>`).join('');els('cart-subtotal').textContent=money(subtotal);els('cart-shipping').textContent=count>=5?'Gratis':count?money(shipping):'—';els('cart-total').textContent=money(subtotal+shipping);els('shipping-note').textContent=count===0?'Añade camisetas para calcular el envío.':count>=5?'Has alcanzado el envío gratis.':`Envío: 3,00 €. Añade ${5-count} ${5-count===1?'camiseta':'camisetas'} más para conseguir envío gratis.`;els('whatsapp-checkout').disabled=count===0;document.querySelectorAll('[data-quantity]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.quantity);cart[i].quantity+=Number(button.dataset.delta);if(cart[i].quantity<=0)cart.splice(i,1);saveCart()});document.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{cart.splice(Number(button.dataset.remove),1);saveCart()})}
function buildOrderMessage(){const count=cart.reduce((sum,item)=>sum+item.quantity,0),subtotal=cart.reduce((sum,item)=>sum+item.unitPrice*item.quantity,0),shipping=count>=5?0:3,lines=cart.map(item=>`${item.quantity} × ${item.name} (${item.season})\n   ${item.version}, talla ${item.size}${item.custom?`, personalización ${[item.customName,item.customNumber].filter(Boolean).join(' ' )||'pendiente de indicar'}`:''}${item.patches?', con parches':''}\n   ${money(item.unitPrice)} c/u = ${money(item.unitPrice*item.quantity)}`).join('\n\n');return `Hola, quiero hacer este pedido en GOLTRA:\n\n${lines}\n\nSubtotal: ${money(subtotal)}\nEnvío: ${shipping?money(shipping):'Gratis'}\nTOTAL ESTIMADO: ${money(subtotal+shipping)}\n\n¿Me confirmáis disponibilidad y los datos para el envío?`}
function sendOrderToWhatsApp(){if(!cart.length)return;window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(buildOrderMessage())}`,'_blank','noopener,noreferrer')}
async function copyOrderToClipboard(){if(!cart.length)return;const message=buildOrderMessage();try{await navigator.clipboard.writeText(message);toast('Pedido copiado. Ya puedes pegarlo en WhatsApp')}catch(error){const field=document.createElement('textarea');field.value=message;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();toast(copied?'Pedido copiado. Ya puedes pegarlo en WhatsApp':'No se pudo copiar. Inténtalo de nuevo')}}
els('copy-order').onclick=copyOrderToClipboard;
els('cart-trigger').onclick=()=>{renderCart();els('cart-dialog').showModal()};els('whatsapp-checkout').onclick=sendOrderToWhatsApp;
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));
