let swipeStart=null;
const gallery=document.querySelector('.detail-main');
gallery.addEventListener('touchstart',e=>{swipeStart={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY}},{passive:true});
gallery.addEventListener('touchend',e=>{if(!swipeStart)return;const dx=e.changedTouches[0].clientX-swipeStart.x,dy=e.changedTouches[0].clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)<45||Math.abs(dx)<Math.abs(dy))return;const p=products.find(x=>x.id===currentId);if(!p)return;const images=productImages(p,els('detail-version').value),index=images.findIndex(path=>storageUrl(path)===els('detail-image').src);selectDetailImage(images[(index+(dx<0?1:-1)+images.length)%images.length],p)},{passive:true});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open')});new MutationObserver(()=>{document.body.classList.toggle('dialog-open',Boolean(document.querySelector('dialog[open]')))}).observe(d,{attributes:true,attributeFilter:['open']})});
